const Module = require('bare-module')
const acorn = require('acorn')
const walk = require('acorn-walk')
const b4a = require('b4a')

module.exports = drive_loader

// runs a js file and everything it requires straight from a drive (autodrive, hyperdrive or a checkout)
// nothing is copied to disk, and code can only require modules outside the drive if they are in builtins
function drive_loader ({ drive, file, builtins = {} }) {
  const protocol = new Module.Protocol({ exists, read })
  const loader = new Module.Loader({ protocol, builtins, defaultType: Module.constants.SCRIPT })
  return loader.import(new URL('drive://' + file))

  async function exists (url) { return (await drive.entry(url.pathname)) !== null }

  async function read (url) {
    const data = await drive.get(url.pathname)
    if (!url.pathname.endsWith('.js')) return data
    const source = b4a.toString(data)
    refuse_dynamic_import(source, url)
    return source
  }
}

/***************************************
REFUSE DYNAMIC IMPORT
import() would load code around the loader, so drive code cant use it
***************************************/
function refuse_dynamic_import (source, url) {
  const ast = acorn.parse(source, { ecmaVersion: 'latest', sourceType: 'script' })
  walk.simple(ast, { ImportExpression () { throw new SyntaxError(`dynamic import is not allowed: ${url.href}`) } })
}
